    /**
     * Method to retrieve the Supplier via SupplierFetchOneSummary
     * @param 	summary SupplierFetchOneSummary 
     * @return 	SupplierFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Supplier getSupplier( SupplierFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "SupplierFetchOneSummary arg cannot be null" );
    	
    	Supplier entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Supplier
        	// --------------------------------------
        	CompletableFuture<Supplier> futureEntity = queryGateway.query(new FindSupplierQuery( new LoadSupplierFilter( summary.getSupplierId() ) ), ResponseTypes.instanceOf(Supplier.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Supplier with id " + summary.getSupplierId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


